                return false;
            }
        }
        return true;
    }

    private boolean isCyclic(List<List<Integer>> graph, int node, boolean[] visited) {
        visited[node] = true;
        for (int neighbor : graph.get(node)) {
            if (!visited[neighbor]) {
                if (!isCyclic(graph, neighbor, visited)) {
                    return true;
                }
            } else if (visited[neighbor]) {
                return true;
            }
        }
        return false;
    }
}

