import java.util.*;

class Solution {
    public int[] smallestMissingValueSubtree(int[] parents, int[] nums) {
        int n = parents.length;
        int[] ans = new int[n];
        List<Set<Integer>> tree = new ArrayList<>();

        for (int i = 0; i < n; i++) {
            tree.add(new HashSet<Integer>());
        }

        dfs(0, parents, nums, tree, ans);
        return ans;
    }

    private void dfs(int node, int[] parents, int[] nums, List<Set<Integer>> tree, int[] ans) {
        tree.get(node).add(nums[node]);
        for (int i = 1; i < parents.length; ++i) {
            if (parents[i] == node) {
                dfs(i, parents, nums, tree, ans);
                tree.get(node).addAll(tree.get(i));
            }
        }
        int missing = 1;
        while (tree.get(node).contains(missing)) ++missing;
        ans[node] = missing;
    }

    // New function to find the length of the longest substring
    public int longestSubstring(String s) {
        int n = s.length();
        int[] count = new int[26];
        int maxLen = 0;
        int start = 0;
        for (int i = 0; i < n; i++) {
            count[s.charAt(i) - 'a']++;
            while (count[s.charAt(i) - 'a'] > 1) {
                count[s.charAt(start) - 'a']--;
                start++;
            }
            maxLen = Math.max(maxLen, i - start + 1);
        }
        return maxLen;
    }
}

